parameters.jsCode:
const body = $input.item.json.body || $input.item.json || {};
const token = (body.token || '').trim();
const action = (body.action || 'CONNECT').toUpperCase();

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!token || !uuidRegex.test(token)) {
  return {
    json: {
      isValid: false,
      error: 'Token de conexão inválido ou não informado.'
    }
  };
}

return {
  json: {
    isValid: true,
    token,
    action
  }
};

const items = $input.all();
const rawLoja = items.length > 0 ? items[0].json : null;
const req = $('Validar Parametros Iniciais').first().json || {};

if (!rawLoja || !rawLoja.id) {
  return {
    json: {
      found: false,
      error: 'Link de conexão inválido, expirado ou loja desativada.'
    }
  };
}

const evoConfig = rawLoja.config_json?.evolutionapi || {};
const defaultEvolutionKey = (rawLoja.config_evo_key || '').trim();
const defaultEvolutionUrl = (rawLoja.config_evo_url || 'https://whats.seudominio.com').replace(/\/+$/, '');

let instanceName = (evoConfig.instanceName || '').trim();
if (!instanceName || instanceName === 'loja-undefined' || instanceName === 'loja-null') {
  instanceName = `loja-${rawLoja.id}`;
}

const apikey = (evoConfig.apikey || '').trim() || defaultEvolutionKey;
let apiUrl = (evoConfig.apiUrl || '').trim().replace(/\/+$/, '');
if (!apiUrl || apiUrl.includes('api.evolution.com.br')) {
  apiUrl = defaultEvolutionUrl;
}

const action = (req.action || 'CONNECT').toUpperCase();
let url = '';
let method = 'GET';

if (action === 'STATUS') {
  url = `${apiUrl}/instance/fetchInstances?instanceName=${instanceName}`;
} else if (action === 'RESTART') {
  url = `${apiUrl}/instance/restart/${instanceName}`;
  method = 'POST';
} else {
  url = `${apiUrl}/instance/connect/${instanceName}`;
}

return {
  json: {
    found: true,
    loja_id: rawLoja.id,
    loja_nome: rawLoja.nome,
    whatsapp_loja: rawLoja.whatsapp_loja,
    instanceName,
    apiUrl,
    apikey,
    action,
    method,
    url
  }
};

const prep = $('Verificar e Preparar Requisicao Evolution').first().json || {};
const raw = $input.item.json || {};
const item = Array.isArray(raw) ? (raw[0] || {}) : raw;

const rawState = item?.connectionStatus || item?.instance?.state || item?.instance?.status || item?.status || item?.state || '';
const stateStr = String(rawState).toLowerCase().trim();

let state = 'unknown';
if (stateStr === 'open' || stateStr === 'connected') {
  state = 'open';
} else if (stateStr === 'connecting') {
  state = 'connecting';
} else if (stateStr === 'close' || stateStr === 'closed' || stateStr === 'disconnected') {
  state = 'close';
}

const rawOwner = item?.ownerJid || item?.owner || item?.number || item?.instance?.ownerJid || item?.instance?.owner || item?.instance?.number || '';
const cleanOwner = rawOwner ? String(rawOwner).split('@')[0].split(':')[0].replace(/\D/g, '') : '';
const owner = cleanOwner ? (cleanOwner.startsWith('55') ? cleanOwner : ('55' + cleanOwner)) : (prep.whatsapp_loja || '');

const base64 = item?.base64 || item?.qrcode?.base64 || null;
const code = item?.code || item?.qrcode?.code || null;

const shouldUpdatePhone = Boolean(state === 'open' && cleanOwner && !prep.whatsapp_loja);

return {
  json: {
    ok: true,
    loja_id: prep.loja_id,
    loja_nome: prep.loja_nome,
    state,
    number: owner || null,
    base64,
    code,
    shouldUpdatePhone,
    ownerPhone: owner
  }
};

const item = $input.item.json || {};
return {
  json: {
    ok: true,
    loja_nome: item.loja_nome,
    state: item.state,
    number: item.number,
    base64: item.base64,
    code: item.code
  }
};

parameters.query:
UPDATE public.lojas
SET whatsapp_loja = $1, updated_at = NOW()
WHERE id = $2 AND (whatsapp_loja IS NULL OR whatsapp_loja = '');
